SELECT 'SW4C_SNAP' AS marker, (SELECT json_group_array(json_object('competition_id',competition_id,'shop_domain',shop_domain,'product_gid',product_gid,'prefix',prefix,'start_number',start_number,'capacity',capacity,'pad_width',pad_width,'handle_snapshot',handle_snapshot,'title_snapshot',title_snapshot,'skill_question_snapshot',skill_question_snapshot,'skill_answers_snapshot',skill_answers_snapshot,'skill_answer_correct_snapshot',skill_answer_correct_snapshot,'status',status,'pool_built_at',pool_built_at,'frozen_at',frozen_at,'created_at',created_at,'updated_at',updated_at)) FROM (SELECT * FROM competition ORDER BY competition_id)) AS competitions, (SELECT json_group_array(json_array(competition_id, seq, entry_number, status, allocation_id, order_id, line_item_id, customer_ref, allocation_seq, allocated_at, released_at, release_reason)) FROM (SELECT * FROM entry_number WHERE competition_id<>'900001' ORDER BY competition_id, seq)) AS entries, (SELECT json_object('n',COUNT(*),'available',SUM(status='AVAILABLE'),'seq_sum',SUM(allocation_seq),'with_alloc',SUM(allocation_id IS NOT NULL OR order_id IS NOT NULL OR line_item_id IS NOT NULL OR allocated_at IS NOT NULL OR released_at IS NOT NULL OR release_reason IS NOT NULL OR customer_ref IS NOT NULL),'min',MIN(entry_number),'max',MAX(entry_number)) FROM entry_number WHERE competition_id='900001') AS put_summary, (SELECT json_group_array(json_array(allocation_id, shop_domain, competition_id, order_id, order_name, order_created_at, line_item_id, variant_id, customer_ref, entry_route, ordered_quantity, entries_per_unit, target_count, held_count, skill_question, skill_answer, skill_answer_correct_snapshot, skill_verdict, skill_judged_at, skill_rule_version, unit_price_minor, line_total_minor, decision_basis, status, source, mirror_state, mirror_attempts, created_at, updated_at)) FROM (SELECT * FROM allocation ORDER BY created_at, allocation_id)) AS allocations, (SELECT json_group_array(json_array(id, occurred_at, competition_id, seq, entry_number, allocation_id, allocation_seq, event_type, from_status, to_status, order_id, customer_ref, reason, actor, run_id, webhook_id, detail_json)) FROM (SELECT * FROM entry_event ORDER BY id)) AS events, (SELECT json_group_array(json_array(webhook_id, topic, received_at, outcome)) FROM webhook_delivery) AS webhook_deliveries, (SELECT json_group_array(json_array(name, seq)) FROM sqlite_sequence) AS sqlite_seq, (SELECT json_object('dup_events',(SELECT COUNT(*) FROM (SELECT allocation_id, entry_number, event_type, occurred_at, COUNT(*) c FROM entry_event GROUP BY 1,2,3,4 HAVING c>1)),'audit_gaps',(SELECT COUNT(*) FROM entry_number n WHERE n.status='ALLOCATED' AND NOT EXISTS (SELECT 1 FROM entry_event e WHERE e.entry_number=n.entry_number AND e.competition_id=n.competition_id)),'ledger_drift',(SELECT COUNT(*) FROM allocation a WHERE a.held_count != (SELECT COUNT(*) FROM entry_number n WHERE n.allocation_id=a.allocation_id AND n.status='ALLOCATED')),'orphans',(SELECT COUNT(*) FROM entry_number n WHERE n.allocation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM allocation a WHERE a.allocation_id=n.allocation_id)),'events_total',(SELECT COUNT(*) FROM entry_event),'allocations_total',(SELECT COUNT(*) FROM allocation),'entry_order_mismatch',(SELECT COUNT(*) FROM entry_number n JOIN allocation a ON a.allocation_id=n.allocation_id WHERE n.status='ALLOCATED' AND (n.order_id<>a.order_id OR n.line_item_id<>a.line_item_id OR n.competition_id<>a.competition_id)),'dup_issue',(SELECT COUNT(*) FROM (SELECT competition_id, seq, allocation_seq FROM entry_event WHERE event_type='ALLOCATED' GROUP BY 1,2,3 HAVING COUNT(*)>1)),'multi_held',(SELECT COUNT(*) FROM (SELECT entry_number FROM entry_number WHERE status='ALLOCATED' GROUP BY 1 HAVING COUNT(DISTINCT allocation_id)>1)),'dup_release',(SELECT COUNT(*) FROM (SELECT competition_id, seq, allocation_seq FROM entry_event WHERE event_type='RELEASED' GROUP BY 1,2,3 HAVING COUNT(*)>1)),'dup_return',(SELECT COUNT(*) FROM (SELECT competition_id, seq, allocation_seq FROM entry_event WHERE event_type='RETURNED_TO_POOL' GROUP BY 1,2,3 HAVING COUNT(*)>1)),'freeze_audit',(SELECT COUNT(*) FROM (SELECT e.status, e.allocation_seq, e.allocation_id, (SELECT COUNT(*) FROM entry_event v WHERE v.competition_id=e.competition_id AND v.seq=e.seq AND v.event_type='ALLOCATED') ae, (SELECT COUNT(*) FROM entry_event v WHERE v.competition_id=e.competition_id AND v.seq=e.seq AND v.event_type='RELEASED') re, (SELECT COUNT(*) FROM entry_event v WHERE v.competition_id=e.competition_id AND v.seq=e.seq AND v.event_type='RETURNED_TO_POOL') te, (SELECT v.allocation_id FROM entry_event v WHERE v.competition_id=e.competition_id AND v.seq=e.seq AND v.event_type='ALLOCATED' AND v.allocation_seq=e.allocation_seq ORDER BY v.id DESC LIMIT 1) ia FROM entry_number e) WHERE ae<>allocation_seq OR re<>allocation_seq-(status='ALLOCATED') OR te<>re-(status='RELEASED') OR (status='ALLOCATED' AND ia IS NOT allocation_id)),'bad_events',(SELECT COUNT(*) FROM entry_event WHERE event_type IN ('REFUSED_CAPACITY','ORDER_HELD','INCORRECT_SKILL','UNJUDGED_SKILL')))) AS integrity